    if cwd.is_empty() { return; }
    // Serialize with sanitize_claude_config and other concurrent launches so the
    // read-modify-write can't interleave and corrupt the file.
    let _guard = CLAUDE_JSON_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let path = home_dir().join(".claude.json");
    let mut config = match std::fs::read_to_string(&path) {
        Ok(content) => match serde_json::from_str::<serde_json::Value>(&content) {
            Ok(v) => v,
            Err(e) => { log::warn!("trust_claude_dir: ~/.claude.json unparseable ({e}); skipping"); return; }
        },
        Err(_) => serde_json::json!({}), // missing file → start fresh
    };
    // Claude Code keys folder-trust on the MAIN repo root: for a linked git WORKTREE it resolves to the
    // git common dir's working tree, NOT the worktree path — so a worker launched in a worktree is only
    // "trusted" if its MAIN repo is trusted, and trusting just the worktree dir is ignored (Claude reads
    // the workspace as untrusted → drops EVERY `permissions.allow` entry → the agent prompts for
    // everything). Trust BOTH the cwd and that main-worktree root so trust applies whichever Claude
    // resolves to (#worktree-trust).
    let keys = trust_keys(cwd, git_main_worktree(cwd).as_deref());
    let mut changed = false;
    for k in &keys {
        if mark_dir_trusted(&mut config, k) { changed = true; }
    }
    if !changed { return; }
    match crate::platform::fsx::atomic_write_json(&path, &config) {
        Ok(())  => log::info!("trust_claude_dir: pre-trusted {}", keys.join(", ")),
        Err(e)  => log::warn!("trust_claude_dir: write {} failed: {e}", path.display()),
    }
}

/// The `~/.claude.json` project keys to pre-trust for a session at `cwd`: the cwd itself, plus the
/// `main_worktree` root when it differs (a linked git worktree's MAIN repo — the dir Claude Code
/// actually keys folder-trust on). Deduped, cwd first. Pure (the git lookup is the caller's job).
fn trust_keys(cwd: &str, main_worktree: Option<&str>) -> Vec<String> {
    let mut keys = vec![claude_project_key(cwd)];
    if let Some(m) = main_worktree.filter(|m| !m.is_empty()) {
        let mk = claude_project_key(m);
        if !keys.contains(&mk) { keys.push(mk); }
    }
    keys
}

/// The MAIN worktree root of the git repo containing `cwd` — the first `worktree <path>` line of
/// `git worktree list --porcelain` (which lists the main worktree first), or `None` when `cwd` isn't
/// a git repo. For a linked worktree this is the MAIN repo — what Claude Code keys folder-trust on
/// (and what the OS sandbox must allow writes to, since a worktree's git data lives there, #1916).
pub(crate) fn git_main_worktree(cwd: &str) -> Option<String> {
    crate::platform::git::git_lines(cwd, &["worktree", "list", "--porcelain"])
        .into_iter()
        .find_map(|l| l.strip_prefix("worktree ").map(|s| s.trim().to_string()))
}

// Reads and writes CLAUDE.md + .claude/settings.json for two target types:
//   global   — local_path = "" → ~/.claude/CLAUDE.md and ~/.claude/settings.json
//   per-repo — local_path = repo root → {root}/CLAUDE.md and {root}/.claude/settings.json

fn claude_paths(local_path: &str) -> (std::path::PathBuf, std::path::PathBuf) {
    if local_path.is_empty() {
        let global = home_dir().join(".claude");
        (global.join("CLAUDE.md"), global.join("settings.json"))
    } else {
        let base = std::path::PathBuf::from(local_path);
        (base.join("CLAUDE.md"), base.join(".claude").join("settings.json"))
    }
}

#[derive(serde::Serialize)]
pub(crate) struct ClaudeConfigData {
    instructions: String,
    allow:        Vec<String>,
    deny:         Vec<String>,
}

#[tauri::command]
pub(crate) fn read_claude_config(local_path: String) -> Result<ClaudeConfigData, String> {
    let (md_path, settings_path) = claude_paths(&local_path);

    let instructions = std::fs::read_to_string(&md_path).unwrap_or_default();

    let (allow, deny) = if settings_path.exists() {
        let raw = std::fs::read_to_string(&settings_path).str_err()?;
        let v: serde_json::Value = serde_json::from_str(&raw).unwrap_or_default();
        let parse_list = |key: &str| -> Vec<String> {
            v["permissions"][key].as_array()
                .map(|a| a.iter().filter_map(|x| x.as_str().map(String::from)).collect())
                .unwrap_or_default()
        };
        (parse_list("allow"), parse_list("deny"))
    } else {
        (vec![], vec![])
    };

    Ok(ClaudeConfigData { instructions, allow, deny })
}

#[tauri::command]
pub(crate) fn write_claude_config(
    local_path: String,
    instructions: String,
    allow: Vec<String>,
    deny: Vec<String>,
) -> Result<(), String> {
    let (md_path, settings_path) = claude_paths(&local_path);

    if let Some(parent) = md_path.parent() {
        std::fs::create_dir_all(parent).str_err()?;
    }
    if let Some(parent) = settings_path.parent() {
        std::fs::create_dir_all(parent).str_err()?;
    }

    crate::platform::fsx::atomic_write(&md_path, instructions.as_bytes()).str_err()?;

    let settings = serde_json::json!({
        "permissions": { "allow": allow, "deny": deny }
    });
    crate::platform::fsx::atomic_write_json(&settings_path, &settings).str_err()?;

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    use super::{claude_project_key, mark_dir_trusted, trust_keys};

    /// The shape check is what keeps a corrupted or hand-edited `~/.claude.json` from putting an
    /// arbitrary string on a command line. It is not a UUID validator — it is a refusal to pass
    /// anything that is not shaped like the id Claude writes.
    #[test]
    fn only_a_session_shaped_id_is_accepted() {
        assert!(plausible_session_id("bf36a25c-b331-48b0-a78c-3bf4e6b51354"));
        assert!(plausible_session_id("00000000-0000-0000-0000-000000000000"));
        for bad in [
            "",
            "bf36a25c",                                     // truncated
            "bf36a25c-b331-48b0-a78c-3bf4e6b5135",          // one short
            "bf36a25c-b331-48b0-a78c-3bf4e6b513545",        // one long
            "bf36a25cXb331-48b0-a78c-3bf4e6b51354",         // dash in the wrong place
            "bf36a25c-b331-48b0-a78c-3bf4e6b5135z",         // not hex
            "; rm -rf ~ #-0000-0000-0000-00000000",         // the reason this exists
        ] {
            assert!(!plausible_session_id(bad), "{bad:?} must be refused");
        }
    }

    #[test]
    fn claude_project_key_uses_forward_slashes_and_upper_drive() {
        // Backslashes → forward slashes; lower-case drive → upper, matching the
        // form Claude Code writes (verified against a real ~/.claude.json).
        assert_eq!(claude_project_key(r"C:\Users\Kevin\proj"), "C:/Users/Kevin/proj");
        assert_eq!(claude_project_key("c:/Users/Kevin/proj"), "C:/Users/Kevin/proj");
        // Already-canonical paths pass through unchanged.
        assert_eq!(
            claude_project_key("C:/Users/Kevin/.base-studio-code/repos/x"),
            "C:/Users/Kevin/.base-studio-code/repos/x"
        );
    }

    #[test]
    fn trust_keys_adds_the_main_worktree_root_for_a_linked_worktree() {
        // A worker in a linked worktree: trust BOTH the worktree dir AND the main repo — Claude Code
        // keys folder-trust on the main repo (the git common dir's working tree), not the worktree.
        let keys = trust_keys(
            "C:/Users/k/.base-studio-code/worktrees/STEM/STEM--backend",
            Some("C:/Users/k/.base-studio-code/projects/STEM/STEM"),
        );
        assert_eq!(keys, vec![
            "C:/Users/k/.base-studio-code/worktrees/STEM/STEM--backend".to_string(),
            "C:/Users/k/.base-studio-code/projects/STEM/STEM".to_string(),
        ]);
    }

    #[test]
    fn trust_keys_is_a_single_key_when_not_a_linked_worktree() {
        let cwd = "C:/Users/k/.base-studio-code/projects/STEM/STEM";
        assert_eq!(trust_keys(cwd, Some(cwd)), vec![cwd.to_string()]); // main == cwd (normal clone)
        assert_eq!(trust_keys(cwd, None), vec![cwd.to_string()]);       // not a git repo
    }

    #[test]
    fn claude_project_key_strips_trailing_slash_and_verbatim_prefix() {
        assert_eq!(claude_project_key("C:/Users/Kevin/proj/"), "C:/Users/Kevin/proj");
        assert_eq!(claude_project_key(r"\\?\C:\Users\Kevin\proj"), "C:/Users/Kevin/proj");
        assert_eq!(claude_project_key("/"), "/"); // bare root preserved
    }

    #[test]
    fn mark_dir_trusted_creates_projects_entry_when_absent() {
        let mut cfg = serde_json::json!({});
        assert!(mark_dir_trusted(&mut cfg, "C:/Users/Kevin/proj"));
        assert_eq!(
            cfg["projects"]["C:/Users/Kevin/proj"]["hasTrustDialogAccepted"],
            serde_json::Value::Bool(true)
        );
    }

    #[test]
    fn mark_dir_trusted_preserves_other_fields_and_sibling_projects() {
        let mut cfg = serde_json::json!({
            "numStartups": 7,
            "projects": {
                "C:/other": { "allowedTools": ["Read"], "hasTrustDialogAccepted": true },
                "C:/proj":  { "allowedTools": ["Edit"], "history": [{ "display": "hi" }] }
            }
        });
        assert!(mark_dir_trusted(&mut cfg, "C:/proj"));
        // Target gains trust without losing its existing fields …
        assert_eq!(cfg["projects"]["C:/proj"]["hasTrustDialogAccepted"], serde_json::Value::Bool(true));
        assert_eq!(cfg["projects"]["C:/proj"]["allowedTools"][0], "Edit");
        assert_eq!(cfg["projects"]["C:/proj"]["history"][0]["display"], "hi");
        // … and unrelated keys / sibling projects are untouched.
        assert_eq!(cfg["numStartups"], 7);
        assert_eq!(cfg["projects"]["C:/other"]["allowedTools"][0], "Read");
    }

    #[test]
    fn mark_dir_trusted_is_noop_when_already_trusted() {
        let mut cfg = serde_json::json!({ "projects": { "C:/proj": { "hasTrustDialogAccepted": true } } });
        assert!(!mark_dir_trusted(&mut cfg, "C:/proj"));
    }

    #[test]
    fn mark_dir_trusted_flips_existing_false_to_true() {
        let mut cfg = serde_json::json!({ "projects": { "C:/proj": { "hasTrustDialogAccepted": false } } });
        assert!(mark_dir_trusted(&mut cfg, "C:/proj"));
        assert_eq!(cfg["projects"]["C:/proj"]["hasTrustDialogAccepted"], serde_json::Value::Bool(true));
    }

    use super::repair_claude_json;

    #[test]
    fn repair_claude_json_passes_through_valid() {
        let out = repair_claude_json(r#"{"a":1,"b":[2,3]}"#).unwrap();
        assert_eq!(serde_json::from_str::<serde_json::Value>(&out).unwrap()["a"], 1);
    }

    #[test]
    fn repair_claude_json_drops_trailing_junk() {
        // The observed corruption: a complete object followed by stray bytes.
        let out = repair_claude_json("{\"a\":1}\n}garbage").unwrap();
        let v: serde_json::Value = serde_json::from_str(&out).unwrap();
        assert_eq!(v["a"], 1);
        assert!(v.get("garbage").is_none());
    }

    #[test]
    fn repair_claude_json_returns_none_for_unrecoverable() {
        assert!(repair_claude_json("not json at all").is_none());
        assert!(repair_claude_json("").is_none());
    }

    #[test]
    fn repair_claude_json_handles_concurrent_write_tail() {
        // The real-world tail: a complete object, then leftover bytes from a
        // longer previous write that wasn't truncated (e.g. `}4\n  }\n}`).
        let out = repair_claude_json("{\n  \"numStartups\": 239,\n  \"ok\": true\n}4\n  }\n}").unwrap();
        let v: serde_json::Value = serde_json::from_str(&out).unwrap();
        assert_eq!(v["numStartups"], 239);
        assert_eq!(v["ok"], true);
    }
}
